import{M as e,O as t,d as n,h as r,p as i}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as a}from"./app-U4R70jmM.js";var o=JSON.parse(`{"path":"/ai-eng/00-setup-and-tooling/12-debugging-and-profiling.html","title":"调试与性能分析","lang":"zh-CN","frontmatter":{},"git":{"createdTime":1787385595000,"updatedTime":1787488693000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":7.16,"words":2147},"filePathRelative":"ai-eng/00-setup-and-tooling/12-debugging-and-profiling.md"}`),s={name:`12-debugging-and-profiling.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="调试与性能分析" tabindex="-1"><a class="header-anchor" href="#调试与性能分析"><span>调试与性能分析</span></a></h1><blockquote><p>最要命的 AI bug 不会崩溃。它们悄无声息地拿垃圾数据训练,还给你画出一条漂亮的 loss 曲线。</p></blockquote><p><strong>类型:</strong> 动手构建<br><strong>编程语言:</strong> Python<br><strong>前置要求:</strong> 第 1 课(开发环境),基本的 PyTorch 使用经验<br><strong>预计耗时:</strong> 约 60 分钟</p><h2 id="学习目标" tabindex="-1"><a class="header-anchor" href="#学习目标"><span>学习目标</span></a></h2><ul><li>用条件 <code>breakpoint()</code> 和 <code>debug_print</code> 在训练途中检查张量形状、dtype 和 NaN 值</li><li>用 <code>cProfile</code>、<code>line_profiler</code>、<code>tracemalloc</code> 给训练循环做性能分析,揪出瓶颈</li><li>识别常见 AI bug:形状不匹配、NaN loss、数据泄漏、设备放错的张量</li><li>配置 TensorBoard,可视化 loss 曲线、权重直方图和梯度分布</li></ul><h2 id="问题" tabindex="-1"><a class="header-anchor" href="#问题"><span>问题</span></a></h2><p>AI 代码的坏法和普通代码不一样。Web 应用崩了会给你堆栈信息。而一个配错的训练循环会跑上 8 小时、烧掉 $200 的 GPU 费用,最后产出一个对所有输入都预测均值的模型。代码从头到尾没报过任何错。bug 可能只是一个放错设备的张量、一个忘了写的 <code>.detach()</code>、或者标签混进了特征里。</p><p>你需要能在这些&quot;静默失败&quot;浪费你的时间和算力之前就把它们逮住的调试工具。</p><h2 id="概念" tabindex="-1"><a class="header-anchor" href="#概念"><span>概念</span></a></h2><p>AI 调试分三个层次:</p>`,10),r(d,{code:`eJw9zz0Lg0AMBuC9vyLc3A+0a+lQuhSkLbSbOKR6aqgmR+4U/Pc9FZolbyB5II2ia+F93UCs7Jib4x7eisTEDVwnxp5Kf/ro4ZyJ91AOOlq/hXhWkeUALNrHGctAIwYS9qaA3e4MWbqSaW7SSFr2ovBwVtethXy16GatCtPa7UjlHO54P9y4hhG7wf7FZBWT3CR7eAXkCrWC5xRa4cW7qMWvE+IQjU6aJj6xBadSU7fE3vaikyk2P2+DUEk=`}),o[1]||=i(`<p>大多数人直接跳到第 3 层(盯着 TensorBoard 看)。但 80% 的 AI bug 藏在第 1 层和第 2 层。</p><div class="language-figure line-numbers-mode" data-highlighter="shiki" data-ext="figure" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-figure"><span class="line"><span>s0-flame-hot</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="动手构建" tabindex="-1"><a class="header-anchor" href="#动手构建"><span>动手构建</span></a></h2><h3 id="第-1-部分-print-调试-没错-就是好使" tabindex="-1"><a class="header-anchor" href="#第-1-部分-print-调试-没错-就是好使"><span>第 1 部分:print 调试(没错,就是好使)</span></a></h3><p>print 调试总被人瞧不起,其实不该。对付张量代码,一条精准的 print 强过在调试器里单步,因为你要同时看到形状、dtype 和取值范围。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> debug_print</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">tensor</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">: shape=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.shape</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, dtype=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.dtype</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, &quot;</span></span>
<span class="line"><span style="color:#C678DD;">          f</span><span style="color:#98C379;">&quot;device=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.device</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, &quot;</span></span>
<span class="line"><span style="color:#C678DD;">          f</span><span style="color:#98C379;">&quot;min=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.</span><span style="color:#61AFEF;">min</span><span style="color:#ABB2BF;">().</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">()</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, max=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.</span><span style="color:#61AFEF;">max</span><span style="color:#ABB2BF;">().</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">()</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, &quot;</span></span>
<span class="line"><span style="color:#C678DD;">          f</span><span style="color:#98C379;">&quot;mean=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.</span><span style="color:#61AFEF;">mean</span><span style="color:#ABB2BF;">().</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">()</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, &quot;</span></span>
<span class="line"><span style="color:#C678DD;">          f</span><span style="color:#98C379;">&quot;has_nan=</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">tensor.</span><span style="color:#61AFEF;">isnan</span><span style="color:#ABB2BF;">().</span><span style="color:#61AFEF;">any</span><span style="color:#ABB2BF;">().</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">()</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在每个可疑操作后面调它。bug 找到后把 print 删掉。就这么简单。</p><h3 id="第-2-部分-python-调试器-pdb-和-breakpoint" tabindex="-1"><a class="header-anchor" href="#第-2-部分-python-调试器-pdb-和-breakpoint"><span>第 2 部分:Python 调试器(pdb 和 breakpoint)</span></a></h3><p>内置调试器在 AI 工作中被低估了。把 <code>breakpoint()</code> 丢进训练循环,就能交互式地检查张量。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> training_step</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">model</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">batch</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">criterion</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">optimizer</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    inputs, labels </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> batch</span></span>
<span class="line"><span style="color:#ABB2BF;">    outputs </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> model</span><span style="color:#ABB2BF;">(inputs)</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> criterion</span><span style="color:#ABB2BF;">(outputs, labels)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> loss.</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">() </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 100</span><span style="color:#C678DD;"> or</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">isnan</span><span style="color:#ABB2BF;">(loss):</span></span>
<span class="line"><span style="color:#56B6C2;">        breakpoint</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">    loss.</span><span style="color:#61AFEF;">backward</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">    optimizer.</span><span style="color:#61AFEF;">step</span><span style="color:#ABB2BF;">()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>进入调试器后,常用命令:</p><ul><li><code>p outputs.shape</code> 看形状</li><li><code>p loss.item()</code> 看 loss 值</li><li><code>p torch.isnan(outputs).sum()</code> 数 NaN 个数</li><li><code>p model.fc1.weight.grad</code> 看梯度</li><li><code>c</code> 继续,<code>q</code> 退出</li></ul><p>这叫条件调试:只在看起来不对劲的时候停下来。对于一万步的训练,这一点至关重要。</p><h3 id="第-3-部分-python-日志-logging" tabindex="-1"><a class="header-anchor" href="#第-3-部分-python-日志-logging"><span>第 3 部分:Python 日志(logging)</span></a></h3><p>当调试不再是&quot;快速看一眼&quot;就能解决时,把 print 换成 logging。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> logging</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">logging.</span><span style="color:#61AFEF;">basicConfig</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    level</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">logging.</span><span style="color:#D19A66;">INFO</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    format</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;</span><span style="color:#D19A66;">%(asctime)s</span><span style="color:#98C379;"> [</span><span style="color:#D19A66;">%(levelname)s</span><span style="color:#98C379;">] </span><span style="color:#D19A66;">%(message)s</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    handlers</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">[</span></span>
<span class="line"><span style="color:#ABB2BF;">        logging.</span><span style="color:#61AFEF;">FileHandler</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;training.log&quot;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">        logging.</span><span style="color:#61AFEF;">StreamHandler</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">    ]</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">logger </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> logging.</span><span style="color:#61AFEF;">getLogger</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">__name__</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">logger.</span><span style="color:#61AFEF;">info</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;Starting training: lr=</span><span style="color:#D19A66;">%.4f</span><span style="color:#98C379;">, batch_size=</span><span style="color:#D19A66;">%d</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">, lr, batch_size)</span></span>
<span class="line"><span style="color:#ABB2BF;">logger.</span><span style="color:#61AFEF;">warning</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;Loss spike detected: </span><span style="color:#D19A66;">%.4f</span><span style="color:#98C379;"> at step </span><span style="color:#D19A66;">%d</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">, loss.</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">(), step)</span></span>
<span class="line"><span style="color:#ABB2BF;">logger.</span><span style="color:#61AFEF;">error</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;NaN loss at step </span><span style="color:#D19A66;">%d</span><span style="color:#98C379;">, stopping&quot;</span><span style="color:#ABB2BF;">, step)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>logging 给你时间戳、严重级别和文件输出。凌晨三点训练挂了,你要的是一份日志文件,而不是早就滚出屏幕的终端输出。</p><h3 id="第-4-部分-给代码段计时" tabindex="-1"><a class="header-anchor" href="#第-4-部分-给代码段计时"><span>第 4 部分:给代码段计时</span></a></h3><p>知道时间花在哪儿,是优化的第一步。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> time</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">class</span><span style="color:#E5C07B;"> Timer</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#56B6C2;"> __init__</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">name</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;&quot;</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#E5C07B;">        self</span><span style="color:#ABB2BF;">.name </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> name</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#56B6C2;"> __enter__</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#E5C07B;">        self</span><span style="color:#ABB2BF;">.start </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> time.</span><span style="color:#61AFEF;">perf_counter</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#E5C07B;"> self</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#56B6C2;"> __exit__</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">, *</span><span style="color:#D19A66;font-style:italic;">args</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">        elapsed </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> time.</span><span style="color:#61AFEF;">perf_counter</span><span style="color:#ABB2BF;">() </span><span style="color:#56B6C2;">-</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">.start</span></span>
<span class="line"><span style="color:#56B6C2;">        print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;[</span><span style="color:#D19A66;">{</span><span style="color:#E5C07B;">self</span><span style="color:#ABB2BF;">.name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">] </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">elapsed</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">s&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#61AFEF;"> Timer</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;data loading&quot;</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    batch </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> next</span><span style="color:#ABB2BF;">(dataloader_iter)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#61AFEF;"> Timer</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;forward pass&quot;</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    outputs </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> model</span><span style="color:#ABB2BF;">(batch)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#61AFEF;"> Timer</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;backward pass&quot;</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss.</span><span style="color:#61AFEF;">backward</span><span style="color:#ABB2BF;">()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常见发现:数据加载占了训练时间的 60%。解法是 DataLoader 里设 <code>num_workers &gt; 0</code>,而不是换更快的 GPU。</p><h3 id="第-5-部分-cprofile-和-line-profiler" tabindex="-1"><a class="header-anchor" href="#第-5-部分-cprofile-和-line-profiler"><span>第 5 部分:cProfile 和 line_profiler</span></a></h3><p>手动计时不够用时:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">python</span><span style="color:#D19A66;"> -m</span><span style="color:#98C379;"> cProfile</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> cumtime</span><span style="color:#98C379;"> train.py</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>它会按累计时间列出所有函数调用。想看逐行的耗时:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">pip</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> line_profiler</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#61AFEF;">@profile</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> train_step</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">model</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">data</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">target</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    output </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> model</span><span style="color:#ABB2BF;">(data)</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> F.</span><span style="color:#61AFEF;">cross_entropy</span><span style="color:#ABB2BF;">(output, target)</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss.</span><span style="color:#61AFEF;">backward</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> loss</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Run with: kernprof -l -v train.py</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第-6-部分-内存分析" tabindex="-1"><a class="header-anchor" href="#第-6-部分-内存分析"><span>第 6 部分:内存分析</span></a></h3><h4 id="用-tracemalloc-看-cpu-内存" tabindex="-1"><a class="header-anchor" href="#用-tracemalloc-看-cpu-内存"><span>用 tracemalloc 看 CPU 内存</span></a></h4><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> tracemalloc</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">tracemalloc.</span><span style="color:#61AFEF;">start</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># your code here</span></span>
<span class="line"><span style="color:#ABB2BF;">model </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> build_model</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">data </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> load_dataset</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">snapshot </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> tracemalloc.</span><span style="color:#61AFEF;">take_snapshot</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">top_stats </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> snapshot.</span><span style="color:#61AFEF;">statistics</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;lineno&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> stat </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> top_stats[:</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">]:</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(stat)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="用-memory-profiler-看-cpu-内存" tabindex="-1"><a class="header-anchor" href="#用-memory-profiler-看-cpu-内存"><span>用 memory_profiler 看 CPU 内存</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">pip</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> memory_profiler</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> memory_profiler </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> profile</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">@profile</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> load_data</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#ABB2BF;">    raw </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> read_csv</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;data.csv&quot;</span><span style="color:#ABB2BF;">)       </span><span style="color:#7F848E;font-style:italic;"># watch memory jump here</span></span>
<span class="line"><span style="color:#ABB2BF;">    processed </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> preprocess</span><span style="color:#ABB2BF;">(raw)       </span><span style="color:#7F848E;font-style:italic;"># and here</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> processed</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用 <code>python -m memory_profiler your_script.py</code> 运行,就能看到逐行的内存占用。</p><h4 id="用-pytorch-看-gpu-内存" tabindex="-1"><a class="header-anchor" href="#用-pytorch-看-gpu-内存"><span>用 PyTorch 看 GPU 内存</span></a></h4><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> torch</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">if</span><span style="color:#ABB2BF;"> torch.cuda.</span><span style="color:#61AFEF;">is_available</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(torch.cuda.</span><span style="color:#61AFEF;">memory_summary</span><span style="color:#ABB2BF;">())</span></span>
<span class="line"></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Allocated: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">torch.cuda.</span><span style="color:#61AFEF;">memory_allocated</span><span style="color:#ABB2BF;">() </span><span style="color:#56B6C2;">/</span><span style="color:#D19A66;"> 1e9</span><span style="color:#C678DD;">:.2f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> GB&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Cached: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">torch.cuda.</span><span style="color:#61AFEF;">memory_reserved</span><span style="color:#ABB2BF;">() </span><span style="color:#56B6C2;">/</span><span style="color:#D19A66;"> 1e9</span><span style="color:#C678DD;">:.2f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> GB&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>撞上 OOM(显存不足)时:</p><ol><li>减小批次大小(永远是第一招)</li><li>用 <code>torch.cuda.empty_cache()</code> 释放缓存显存</li><li>对大型中间张量,先 <code>del tensor</code> 再 <code>torch.cuda.empty_cache()</code></li><li>用混合精度(<code>torch.cuda.amp</code>)把显存占用减半</li><li>对特别深的模型用梯度检查点(gradient checkpointing)</li></ol><h3 id="第-7-部分-常见-ai-bug-及抓捕方法" tabindex="-1"><a class="header-anchor" href="#第-7-部分-常见-ai-bug-及抓捕方法"><span>第 7 部分:常见 AI bug 及抓捕方法</span></a></h3><h4 id="形状不匹配" tabindex="-1"><a class="header-anchor" href="#形状不匹配"><span>形状不匹配</span></a></h4><p>最高发的 bug。张量是 <code>[batch, features]</code>,模型要的却是 <code>[batch, channels, height, width]</code>。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> check_shapes</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">model</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">sample_input</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Input: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">sample_input.shape</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    hooks </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> []</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#61AFEF;"> make_hook</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">name</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">        def</span><span style="color:#61AFEF;"> hook</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">module</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">inp</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">out</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">            in_shape </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> inp[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">].shape </span><span style="color:#C678DD;">if</span><span style="color:#56B6C2;"> isinstance</span><span style="color:#ABB2BF;">(inp, </span><span style="color:#56B6C2;">tuple</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">else</span><span style="color:#ABB2BF;"> inp.shape</span></span>
<span class="line"><span style="color:#ABB2BF;">            out_shape </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> out.shape </span><span style="color:#C678DD;">if</span><span style="color:#56B6C2;"> hasattr</span><span style="color:#ABB2BF;">(out, </span><span style="color:#98C379;">&quot;shape&quot;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">else</span><span style="color:#56B6C2;"> type</span><span style="color:#ABB2BF;">(out)</span></span>
<span class="line"><span style="color:#56B6C2;">            print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;  </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">in_shape</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> -&gt; </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">out_shape</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#ABB2BF;"> hook</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> name, module </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> model.</span><span style="color:#61AFEF;">named_modules</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#ABB2BF;">        hooks.</span><span style="color:#61AFEF;">append</span><span style="color:#ABB2BF;">(module.</span><span style="color:#61AFEF;">register_forward_hook</span><span style="color:#ABB2BF;">(</span><span style="color:#61AFEF;">make_hook</span><span style="color:#ABB2BF;">(name)))</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    with</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">no_grad</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#61AFEF;">        model</span><span style="color:#ABB2BF;">(sample_input)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> h </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> hooks:</span></span>
<span class="line"><span style="color:#ABB2BF;">        h.</span><span style="color:#61AFEF;">remove</span><span style="color:#ABB2BF;">()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>拿一个样本批次跑一遍,模型里每一次形状变换都清清楚楚。</p><h4 id="nan-损失-nan-loss" tabindex="-1"><a class="header-anchor" href="#nan-损失-nan-loss"><span>NaN 损失(NaN Loss)</span></a></h4><p>NaN loss 意味着有东西炸了。常见原因:</p><ul><li>学习率太高</li><li>自定义 loss 里除以零</li><li>对零或负数取了 log</li><li>RNN 里梯度爆炸</li></ul><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> detect_nan</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">model</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">loss</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">step</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">isnan</span><span style="color:#ABB2BF;">(loss):</span></span>
<span class="line"><span style="color:#56B6C2;">        print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;NaN loss at step </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">step</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">        for</span><span style="color:#ABB2BF;"> name, param </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> model.</span><span style="color:#61AFEF;">named_parameters</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#C678DD;">            if</span><span style="color:#ABB2BF;"> param.grad </span><span style="color:#C678DD;">is</span><span style="color:#C678DD;"> not</span><span style="color:#D19A66;"> None</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#C678DD;">                if</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">isnan</span><span style="color:#ABB2BF;">(param.grad).</span><span style="color:#61AFEF;">any</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#56B6C2;">                    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;  NaN gradient in </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">                if</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">isinf</span><span style="color:#ABB2BF;">(param.grad).</span><span style="color:#61AFEF;">any</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#56B6C2;">                    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;  Inf gradient in </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#D19A66;"> True</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> False</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="数据泄漏" tabindex="-1"><a class="header-anchor" href="#数据泄漏"><span>数据泄漏</span></a></h4><p>模型在测试集上拿了 99% 准确率。听起来很美,其实是 bug。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> check_data_leakage</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">train_set</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">test_set</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">id_column</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;id&quot;</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    train_ids </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> set</span><span style="color:#ABB2BF;">(train_set[id_column].</span><span style="color:#61AFEF;">tolist</span><span style="color:#ABB2BF;">())</span></span>
<span class="line"><span style="color:#ABB2BF;">    test_ids </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> set</span><span style="color:#ABB2BF;">(test_set[id_column].</span><span style="color:#61AFEF;">tolist</span><span style="color:#ABB2BF;">())</span></span>
<span class="line"><span style="color:#ABB2BF;">    overlap </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> train_ids </span><span style="color:#56B6C2;">&amp;</span><span style="color:#ABB2BF;"> test_ids</span></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> overlap:</span></span>
<span class="line"><span style="color:#56B6C2;">        print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;DATA LEAKAGE: </span><span style="color:#D19A66;">{</span><span style="color:#56B6C2;">len</span><span style="color:#ABB2BF;">(overlap)</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> samples in both train and test&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#D19A66;"> True</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> False</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>还要查时间维度的泄漏:用未来的数据预测过去。划分前先按时间戳排序。</p><h4 id="设备放错" tabindex="-1"><a class="header-anchor" href="#设备放错"><span>设备放错</span></a></h4><p>张量在不同设备上(CPU 和 GPU 混着)会直接报运行时错误。但有时候某个张量悄悄留在 CPU 上,其他都在 GPU 上,训练只是变慢了,什么都不报。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> check_devices</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">model</span><span style="color:#ABB2BF;">, *</span><span style="color:#D19A66;font-style:italic;">tensors</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    model_device </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> next</span><span style="color:#ABB2BF;">(model.</span><span style="color:#61AFEF;">parameters</span><span style="color:#ABB2BF;">()).device</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Model device: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">model_device</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> i, t </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> enumerate</span><span style="color:#ABB2BF;">(tensors):</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> t.device </span><span style="color:#56B6C2;">!=</span><span style="color:#ABB2BF;"> model_device:</span></span>
<span class="line"><span style="color:#56B6C2;">            print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;  WARNING: tensor </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">i</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> on </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">t.device</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, model on </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">model_device</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第-8-部分-tensorboard-基础" tabindex="-1"><a class="header-anchor" href="#第-8-部分-tensorboard-基础"><span>第 8 部分:TensorBoard 基础</span></a></h3><p>TensorBoard 让你看到训练过程中随时间发生的一切。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">pip</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> tensorboard</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> torch.utils.tensorboard </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> SummaryWriter</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">writer </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> SummaryWriter</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;runs/experiment_1&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> step </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(num_steps):</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> train_step</span><span style="color:#ABB2BF;">(model, batch)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">    writer.</span><span style="color:#61AFEF;">add_scalar</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;loss/train&quot;</span><span style="color:#ABB2BF;">, loss.</span><span style="color:#61AFEF;">item</span><span style="color:#ABB2BF;">(), step)</span></span>
<span class="line"><span style="color:#ABB2BF;">    writer.</span><span style="color:#61AFEF;">add_scalar</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;lr&quot;</span><span style="color:#ABB2BF;">, optimizer.param_groups[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&quot;lr&quot;</span><span style="color:#ABB2BF;">], step)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> step </span><span style="color:#56B6C2;">%</span><span style="color:#D19A66;"> 100</span><span style="color:#56B6C2;"> ==</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#C678DD;">        for</span><span style="color:#ABB2BF;"> name, param </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> model.</span><span style="color:#61AFEF;">named_parameters</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#ABB2BF;">            writer.</span><span style="color:#61AFEF;">add_histogram</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;weights/</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">, param, step)</span></span>
<span class="line"><span style="color:#C678DD;">            if</span><span style="color:#ABB2BF;"> param.grad </span><span style="color:#C678DD;">is</span><span style="color:#C678DD;"> not</span><span style="color:#D19A66;"> None</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">                writer.</span><span style="color:#61AFEF;">add_histogram</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;grads/</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">name</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">, param.grad, step)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">writer.</span><span style="color:#61AFEF;">close</span><span style="color:#ABB2BF;">()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>启动:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">tensorboard</span><span style="color:#D19A66;"> --logdir=runs</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>看什么:</p><ul><li><strong>Loss 不降</strong>:学习率太低,或模型结构有问题</li><li><strong>Loss 剧烈震荡</strong>:学习率太高</li><li><strong>Loss 变成 NaN</strong>:数值不稳定(见上面的 NaN 部分)</li><li><strong>训练 loss 在降、验证 loss 在升</strong>:过拟合</li><li><strong>权重直方图塌缩到零</strong>:梯度消失</li><li><strong>梯度直方图爆炸</strong>:该上梯度裁剪了</li></ul><h3 id="第-9-部分-vs-code-调试器" tabindex="-1"><a class="header-anchor" href="#第-9-部分-vs-code-调试器"><span>第 9 部分:VS Code 调试器</span></a></h3><p>交互式调试,给 VS Code 配一个 <code>launch.json</code>:</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-json"><span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;version&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;0.2.0&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;configurations&quot;</span><span style="color:#ABB2BF;">: [</span></span>
<span class="line"><span style="color:#ABB2BF;">        {</span></span>
<span class="line"><span style="color:#E06C75;">            &quot;name&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;Debug Training&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">            &quot;type&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;debugpy&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">            &quot;request&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;launch&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">            &quot;program&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;\${file}&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">            &quot;console&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;integratedTerminal&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">            &quot;justMyCode&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">false</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"><span style="color:#ABB2BF;">    ]</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>点行号旁边的边栏设断点。用变量面板查看张量属性。调试控制台可以在执行到一半时跑任意 Python 表达式。</p><p>单步跟踪数据预处理流水线、想看每一步变换时,这个特别好用。</p><h2 id="投入使用" tabindex="-1"><a class="header-anchor" href="#投入使用"><span>投入使用</span></a></h2><p>能逮住大多数 AI bug 的调试流程:</p><ol><li><strong>训练前</strong>:用样本批次跑 <code>check_shapes</code>,确认输入输出维度符合预期。</li><li><strong>头 10 步</strong>:对 loss、输出、梯度用 <code>debug_print</code>,确认没有 NaN、取值在合理范围。</li><li><strong>训练中</strong>:记录 loss、学习率、梯度范数,用 TensorBoard 可视化。</li><li><strong>出问题时</strong>:在故障点丢一个 <code>breakpoint()</code>,交互式检查张量。</li><li><strong>搞性能时</strong>:分别计时数据加载、前向、反向。快 OOM 了就做内存分析。</li></ol><h2 id="交付" tabindex="-1"><a class="header-anchor" href="#交付"><span>交付</span></a></h2><p>运行调试工具脚本:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">python</span><span style="color:#98C379;"> phases/00-setup-and-tooling/12-debugging-and-profiling/code/debug_tools.py</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>另见 <code>outputs/prompt-debug-ai-code.md</code>,里面有一条帮你诊断 AI 专属 bug 的提示词。</p><h2 id="练习" tabindex="-1"><a class="header-anchor" href="#练习"><span>练习</span></a></h2><ol><li>运行 <code>debug_tools.py</code>,通读每一部分的输出。改动那个示例模型引入一个 NaN(提示:在前向传播里除以零),看检测器逮住它。</li><li>用 <code>cProfile</code> 分析一个训练循环,找出最慢的函数。</li><li>用 <code>tracemalloc</code> 找出数据加载流水线里分配内存最多的那一行。</li><li>给一个简单训练任务配上 TensorBoard,判断模型是否过拟合。</li><li>在训练循环里用 <code>breakpoint()</code>,练习在调试器提示符下检查张量形状、设备和梯度值。</li></ol>`,76)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};